(* [comment removed for export] *)
Definition vals0 (j : nat) : Z := match j with 2%nat => spc | 3%nat => pa_gp AD | 4%nat => hl_tp L | 8%nat => sp | 9%nat => spc | _ => 0 end.
Definition IX0 : list nat := [2; 3; 4; 8; 9]%nat.
Local Notation REG0 := (regl IX0 vals0).
(* [comment removed for export] *)
Definition cells (l : list (Z * Z)) (Mx : mem) : Prop := forall p, In p l -> L5.u64_at RSEGS Mx (fst p) (snd p).
Lemma cells_keep l (Ma Mb : mem) lo hi : (forall a, lo <= a < hi -> Mb (Z_to_bv 64 a) = Ma (Z_to_bv 64 a)) -> 0 <= lo -> hi <= 2 ^ 64 ->
