Lemma CPRCALL D1 (INC1 : incl D D1) BX1 Aw1 cr1 (lo k : Z) M3 model3 LK3 (fx3 : FPState) R3 (ra fbs : Z) (len : nat) (s0 s1 : Z) :
  GM [D1] BX1 M3 model3 LK3 Aw1 cr1 -> (lo = 216 \/ lo = 184) -> 32 <= k -> k + 32 <= 504 -> k mod 8 = 0 ->
  getr R3 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> REG0 R3 -> getr R3 (reg 10) = Z_to_bv 64 (spc + lo) -> getr R3 (reg 11) = Z_to_bv 64 (F + k) ->
  PQATSS.binl_at RSEGS M3 (F + k) fbs len s0 s1 -> shz M3 (k / 8) ->
  (forall (fx4 : FPState) R4 (M4 : mem) model4 LK4 (fb' : Z),
      GM [D1] BX1 M4 model4 LK4 Aw1 cr1 -> regs_preserved R3 R4 ->
      PQATSS.binl_at RSEGS M4 (spc + lo) fb' len s0 s1 -> Z.land fb' 2 = Z.land fbs 2 -> PQATSS.binl_at RSEGS M4 (F + k) fbs len s0 s1 ->
      keptS lo 32 (fun _ => False) M3 M4 -> (forall q, In (q, 64) (BX1 ++ LBX) -> PMFA.agA M3 M4 q 64) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx4 R4 ra M4 model4) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx3 R3 CPYPC M3 model3) K.
Proof.
