(* [comment removed for export] *)
Lemma NRMCALL D1 (INC1 : incl D D1) BX1 Aw1 cr1 M3 model3 LK3 (fx3 : FPState) R3 (ra th fd fn : Z) (pn : Z) :
  GM [D1] BX1 M3 model3 LK3 Aw1 cr1 ->
  getr R3 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> REG0 R3 -> getr R3 (reg 10) = Z_to_bv 64 th -> getr R3 (reg 11) = Z_to_bv 64 (F + 32) ->
  getr R3 (reg 12) = Z_to_bv 64 (F + 96) -> getr R3 (reg 13) = Z_to_bv 64 (spc + 180) ->
  PQATSS.binl_at RSEGS M3 (F + 32) fd 1%nat PQATSC.TEN19 d1 -> PQATSW2.bdyn_at RSEGS M3 (F + 96) fn 2%nat pn v0 v1 -> In (pn, 64) (BX1 ++ LBX) -> shz M3 4 -> shz M3 12 ->
  (forall (fx4 : FPState) R4 (M4 : mem) model4 LK4,
      GM [D1] BX1 M4 model4 LK4 Aw1 cr1 -> regs_preserved R3 R4 -> getr R4 (reg 10) = Z_to_bv 64 0 ->
      PQATSS.binl_at RSEGS M4 (F + 32) fd 1%nat PQATSC.TEN19 d1 -> PQATSW2.bdyn_at RSEGS M4 (F + 96) fn 2%nat pn v0 v1 -> L5.u32_at RSEGS M4 (spc + 180) 0 ->
      keptS 180 4 (fun a => inx (F + 32) a \/ inx (F + 96) a) M3 M4 -> (forall q, In (q, 64) (BX1 ++ LBX) -> PMFA.agA M3 M4 q 64) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx4 R4 ra M4 model4) K) ->
