(* [comment removed for export] *)
Lemma RDXCALL D1 (INC1 : incl D D1) BX1 Aw1 cr1 M3 model3 LK3 (fx3 : FPState) R3 (ra fbx e0 e1 : Z) :
  GM [D1] BX1 M3 model3 LK3 Aw1 cr1 ->
  getr R3 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> REG0 R3 -> getr R3 (reg 10) = Z_to_bv 64 o ->
  PQATSW2.bdyn_at RSEGS M3 o fbx 1%nat pb e0 e1 -> 1 <= e0 ->
  (forall (fx4 : FPState) R4 (M4 : mem) model4 LK4,
      GM [D1] BX1 M4 model4 LK4 Aw1 cr1 -> regs_preserved R3 R4 -> getr R4 (reg 10) = Z_to_bv 64 o ->
      PQATSW2.bdyn_at RSEGS M4 o fbx 1%nat pb e0 e1 -> kept (fun _ => False) M3 M4 -> (forall q, In (q, 64) (BX1 ++ LBX) -> PMFA.agA M3 M4 q 64) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx4 R4 ra M4 model4) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx3 R3 REDPC M3 model3) K.
Proof.
