(* [comment removed for export] *)
Lemma CPXCALLS D1 (INC1 : incl D D1) BX1 Aw1 cr1 M3 model3 LK3 (fx3 : FPState) R3 (ra fbs pn : Z) :
  GM [D1] BX1 M3 model3 LK3 Aw1 cr1 ->
  getr R3 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> REG0 R3 -> getr R3 (reg 10) = Z_to_bv 64 (spc + 216) -> getr R3 (reg 11) = Z_to_bv 64 (F + 96) -> shz M3 12 ->
  PQATSW2.bdyn_at RSEGS M3 (F + 96) fbs 2%nat pn v0 v1 -> In (pn, 64) (BX1 ++ LBX) -> PQATSG.gpre L LR PQATSG.OPNEW_RA_A D1 64 cr1 ->
  (forall (fx4 : FPState) R4 (M4 : mem) model4 LK4 Aw4 cr4 (q fn : Z) (gk : list Z),
      GM [gk :: D1] ((q, 64) :: BX1) M4 model4 LK4 Aw4 cr4 -> regs_preserved R3 R4 -> In gk (PQATSG.GKEYS LR PQATSG.OPNEW_RA_A) ->
