Lemma OPDCALL D1 (INC1 : incl D D1) BX1 Aw1 cr1 (q : Z) M3 model3 LK3 (fx3 : FPState) R3 (ra : Z) :
  GM [D1] ((q, 64) :: BX1) M3 model3 LK3 Aw1 cr1 ->
  getr R3 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> 4096 <= ra -> REG0 R3 -> getr R3 (reg 10) = Z_to_bv 64 q ->
  (forall (fx4 : FPState) R4 (M4 : mem) model4 Aw4 (Kt : list Z),
      GM [Kt :: D1] BX1 M4 model4 LK3 Aw4 (if HAR.warm_ok Kt D1 64 then (fst cr1 + 1, snd cr1) else cr1) -> regs_preserved R3 R4 ->
      In Kt (PQATSTW.fkeys3 (HAR.hlr_pc_free LR) ra r RC) ->
