(* [comment removed for export] *)
Lemma AGBP D1 (INC1 : incl D D1) BX1 Aw1 cr1 M1 model1 LK1 (Ma Mb : mem) (Wp : Z -> Prop) :
  GM [D1] BX1 M1 model1 LK1 Aw1 cr1 ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ Wp a -> Mb (Z_to_bv 64 a) = Ma (Z_to_bv 64 a)) ->
  (forall a, Wp a -> (spc <= a < sp) \/ (F <= a < F + 512) \/ (F / 8 + SB <= a < F / 8 + SB + 64) \/ (o <= a < o + 32) \/ (rr <= a < rr + 32)) ->
