(* [comment removed for export] *)
Local Notation GK := (PQATSG.GKEYS LR PQATSG.OPNEW_RA_A).
Local Notation P0F := (HAR.hlr_pc_free LR).

(* [comment removed for export] *)
Lemma LPP (gk1 gk2 Kt1 : list Z) (cr1 cr2 : credit) (pn : Z) Aw3 M5 model5 LK5 (fx5 : FPState) R5 (fbq fbr' fn fd : Z) :
  In gk1 GK -> In gk2 GK ->
  PMSP.credit_keep cr cr1 (PQATSG.gcostD L gk1 D 64) PMSP.cr0 -> PMSP.credit_keep cr1 cr2 (PQATSG.gcostD L gk2 (gk1 :: D) 64) PMSP.cr0 ->
  In Kt1 (PQATSTW.fkeys3 P0F PQATSTW.DIV_FREE0_RA r RC) ->
  GM [Kt1 :: gk2 :: gk1 :: D] [(pn, 64)] M5 model5 LK5 Aw3 (if HAR.warm_ok Kt1 (gk2 :: gk1 :: D) 64 then (fst cr2 + 1, snd cr2) else cr2) ->
  PQATSW2.bdyn_at RSEGS M5 o fbq 1%nat pb (VV / PQATSC.TEN19) v1 -> Z.land fbq 2 = Z.land fb 2 ->
  PQATSS.binl_at RSEGS M5 rr fbr' (PQATSS.wlen (VV mod PQATSC.TEN19) 0) (VV mod PQATSC.TEN19) 0 -> Z.land fbr' 2 = Z.land fb 2 ->
  PQATSW2.bdyn_at RSEGS M5 (F + 96) (Z.land fn 253) 2%nat pn v0 v1 -> 0 <= fn <= 255 -> Z.testbit fn 0 = true ->
  L5.u8_at RSEGS M5 (F + 32) (Z.land fd 253) -> 0 <= fd <= 255 -> Z.testbit fd 0 = false ->
  REG0 R5 -> getr R5 (reg 18) = Z_to_bv 64 (F / 8 + 2147450880) ->
  getr R5 (reg 20) = Z_to_bv 64 (F + 32) -> getr R5 (reg 21) = Z_to_bv 64 (F + 96) -> getr R5 (reg 24) = Z_to_bv 64 F -> getr R5 (reg 27) = Z_to_bv 64 F ->
