Lemma LPJ (gk1 gk2 : list Z) (cr1 cr2 : credit) (pn pn0 : Z) Aw2 M5 model5 LK5 (fx5 : FPState) R5 (fn fd fn0 fd0 : Z) :
  In gk1 GK -> In gk2 GK ->
  PMSP.credit_keep cr cr1 (PQATSG.gcostD L gk1 D 64) PMSP.cr0 -> PMSP.credit_keep cr1 cr2 (PQATSG.gcostD L gk2 (gk1 :: D) 64) PMSP.cr0 ->
  GM [gk2 :: gk1 :: D] [(pn0, 64); (pn, 64)] M5 model5 LK5 Aw2 cr2 ->
  PQATSW2.bdyn_at RSEGS M5 o fb 1%nat pb 0 v1 ->
  PQATSS.binl_at RSEGS M5 rr fbr lenr r0 r1 ->
  PQATSW2.bdyn_at RSEGS M5 (F + 96) (Z.land fn 253) 2%nat pn v0 v1 -> 0 <= fn <= 255 -> Z.testbit fn 0 = true ->
  PQATSS.binl_at RSEGS M5 (F + 32) (Z.land fd 253) 1%nat PQATSC.TEN19 d1 -> 0 <= fd <= 255 -> Z.testbit fd 0 = false ->
  PQATSW2.bdyn_at RSEGS M5 (spc + 216) fn0 2%nat pn0 v0 v1 -> PQATSS.binl_at RSEGS M5 (spc + 184) fd0 1%nat PQATSC.TEN19 d1 ->
