  REG0 R5 -> getr R5 (reg 18) = Z_to_bv 64 (o / 8 + 2147450880) -> getr R5 (reg 20) = Z_to_bv 64 (F + 96) -> getr R5 (reg 21) = Z_to_bv 64 2147450880 ->
  getr R5 (reg 23) = Z_to_bv 64 rr -> getr R5 (reg 24) = Z_to_bv 64 pb -> getr R5 (reg 27) = Z_to_bv 64 2 ->
