Lemma BD3 (gk1 : list Z) (cr1 : credit) (pn : Z) Aw1 M3 model3 LK3 (fx3 : FPState) R3 (fn fd : Z) :
  In gk1 GK -> PMSP.credit_keep cr cr1 (PQATSG.gcostD L gk1 D 64) PMSP.cr0 ->
  GM [gk1 :: D] [(pn, 64)] M3 model3 LK3 Aw1 cr1 ->
  PQATSW2.bdyn_at RSEGS M3 o fb 2%nat pb v0 v1 ->
  PQATSS.binl_at RSEGS M3 rr fbr lenr r0 r1 ->
  PQATSW2.bdyn_at RSEGS M3 (F + 96) fn 2%nat pn v0 v1 ->
  PQATSS.binl_at RSEGS M3 (F + 32) fd 1%nat PQATSC.TEN19 d1 -> Z.testbit fd 1 = false ->
  shz M3 12 -> shz M3 4 ->
  cells [(V2 - 200, 2147450880); (V2 - 240, F / 8 + 2147450880); (V2 - 280, F); (V2 - 256, rr); (V2 - 192, F); (V2 - 208, o); (V2 - 248, o); (V2 - 304, 1); (V2 - 264, F + 32)] M3 ->
  REG0 R3 -> getr R3 (reg 18) = Z_to_bv 64 (F / 8 + 2147450880) -> getr R3 (reg 19) = Z_to_bv 64 (o / 8 + 2147450880) ->
  getr R3 (reg 20) = Z_to_bv 64 1 -> getr R3 (reg 21) = Z_to_bv 64 fd -> getr R3 (reg 22) = Z_to_bv 64 fb -> getr R3 (reg 23) = Z_to_bv 64 (F + 32) ->
  getr R3 (reg 24) = Z_to_bv 64 (F + 96) -> getr R3 (reg 26) = Z_to_bv 64 (F + 48) -> getr R3 (reg 27) = Z_to_bv 64 F ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx3 R3 RA_C2 M3 model3) K.
